import React, { useEffect } from 'react';

export default function AboutMe({ theme }) {
  useEffect(() => {
    // 1) Load the LinkedIn platform script once
    if (!document.getElementById('linkedin-platform')) {
      const injs = document.createElement('script');
      injs.src = 'https://platform.linkedin.com/in.js';
      injs.type = 'text/javascript';
      injs.async = true;
      // this tells the library which locale to use
      injs.innerHTML = 'lang: en_US';
      injs.id = 'linkedin-platform';
      document.body.appendChild(injs);
    }

    // 2) Inject the MemberProfile plugin
    const container = document.getElementById('linkedin-profile-container');
    container.innerHTML = ''; // clear any previous
    const profile = document.createElement('script');
    profile.type = 'IN/MemberProfile';
    profile.setAttribute(
      'data-id',
      'https://www.linkedin.com/in/srivikaatr'
    );
    profile.setAttribute('data-format', 'inline');
    profile.setAttribute('data-related', 'false');
    container.appendChild(profile);
  }, []);

  return (
    <section id="about" className="py-12">
      <h2
        className={`
          text-2xl font-bold mb-6
          ${theme === 'dark' ? 'text-yellow-400' : 'text-blue-800'}
        `}
      >
        About Me
      </h2>

      <div className="grid md:grid-cols-2 gap-8 items-start">
        {/* Left: your bio text */}
        <div
          className={`
            space-y-4
            ${theme === 'dark' ? 'text-yellow-300' : 'text-blue-600'}
          `}
        >
          <p>
            I’m a Running Start student at SPSCC pursuing an A.A. in Computer Science and an
            aspiring Electrical &amp; Computer Engineer. Over the past three years, I’ve led
            robotics teams, founded STEM outreach programs, and completed a Headstarter AI
            Fellowship.
          </p>
          <p>
            As captain of FRC Team 4450, I restructured leadership and ran rookie workshops;
            as founder of FIRST STEP ORG, I launched six FLL teams and mentored over 60
            students; and through my fellowship, I mastered HTML, CSS, JavaScript, and
            Git workflows.
          </p>
        </div>

        {/* Right: LinkedIn MemberProfile */}
        <div id="linkedin-profile-container" />
      </div>
    </section>
  );
}
